SELECT EXISTS(
    SELECT 1
    FROM child c
    WHERE c.child_id = #{childId}
)

SELECT EXISTS(
    SELECT 1
    FROM child_parent cp
    INNER JOIN member m
        ON m.member_id = cp.member_id
    WHERE cp.child_id = #{childId}
      AND cp.member_id = #{memberId}
      AND m.status = 'ACTIVE'
)

SELECT

FROM time_capsule tc
WHERE tc.child_id = #{childId}
  AND tc.financial_account_id = #{financialAccountId}
  AND tc.deleted_at IS NULL
